"""Generate LUT transport registry from the adjacent Python reference."""
import json
from pathlib import Path
from spektrafilm_lut_creator import color_spaces as c
m={None:'Linear','sRGB':'Srgb','ITU-R BT.1886':'Gamma(2.4)','Gamma 2.6':'Gamma(2.6)','Gamma 2.2':'Gamma(2.2)','ACEScct':'Acescct','ACEScc':'Acescc','ARRI LogC3':'Logc3','ARRI LogC4':'Logc4','S-Log3':'Slog3','V-Log':'Vlog','F-Log':'Flog','F-Log2':'Flog2','Canon Log 3':'Canonlog3','Log3G10':'Log3g10','DaVinci Intermediate':'DaVinci','Apple Log Profile':'Applelog','Blackmagic Film Generation 5':'Blackmagic5','ITU-R BT.2100 PQ':'Pq','ITU-R BT.2100 HLG':'Hlg','D-Log':'Dlog','ProPhoto RGB':'ProPhoto','N-Log':'Nlog'}
rows=[]
for e in c._REGISTRY.values():
 rows.append(f'LutSpace {{name:{json.dumps(e.name)}, primaries:{json.dumps(e.primaries)}, tag:{json.dumps(e.short_tag)}, input_role:{str("input" in e.role).lower()}, output_role:{str("output" in e.role).lower()}, curve:Transfer::{m[e.cctf]}, midgray_linear:{e.midgray_linear!r}, auto_gain:{c.input_gain(e.name)!r}, output_gain:{c.output_midgray_gain(e.name)!r} }},')
Path('crates/spektrafilm-core/src/lut_spaces.rs').write_text('// Generated by scripts/reference/generate_lut_spaces.py.\nuse super::lut_export::LutSpace;\nuse spektrafilm_math::transfer::Transfer;\npub static SPACES: &[LutSpace] = &[\n'+ '\n'.join(rows)+'\n];\n')
